    planned.set_viewport(400, 400, 1.0);
    direct.wheel_screen(160.0, 190.0, 0.0, -10.0, true);
    let plan = planned.plan_wheel(160.0, 190.0, 0.0, -10.0, true);
    assert!(planned.commit_wheel(plan));
