    pub fn remove_output_port(&mut self, widget_id: &str, port_id: &str) -> Result<(), FlowCoreError> {
        self.begin_change();
        let neuron_kind = self
            .host_snapshot
            .widgets
            .iter()
            .find_map(|widget| match widget {
