    pub fn load_host_snapshot_json(json: &str) -> Result<Self, DagError> {
        let host_snapshot: DagHostSnapshot = semio_framework_pack_json::from_json_str(json, semio_framework_pack_json::JsonMemberPolicy::Reject)?;
