            PortShape::Triangle => handle_exterior_cap_triangle_fill_path(center, outward, radius),
        }
    }

    fn handle_cap_stroke_path(&self, center: canvas::Point, outward: canvas::Vec2, radius: f64, shape: PortShape) -> canvas::BezPath {
        match shape {
