    let port_idx = combine.inputs().iter().position(|p| p.id == "b").expect("port b");
    let (x0, y0, x1, y1) = input_port_row_hit_bounds(combine, port_idx).expect("row bounds");
    let row_center = canvas::Point::new((x0 + x1) * 0.5, (y0 + y1) * 0.5);
